<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap.php';
use School\Core\SchoolAuth;
use School\Core\SchoolDatabase;
use School\Services\AuditService;
SchoolAuth::requireLogin();$user=SchoolAuth::user();$role=school_current_role($user);$canStaff=SchoolAuth::hasPermission('staff.manage');$canAssign=SchoolAuth::hasPermission('assignments.manage');if(!$canStaff&&!$canAssign){http_response_code(403);exit('Staff access is not permitted.');}$pdo=SchoolDatabase::connection();$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!SchoolAuth::verifyCsrf())$error='Your session expired. Please try again.';
 else try{$action=(string)($_POST['action']??'');
  if($action==='create_staff'&&$canStaff){$userId=(int)($_POST['user_id']??0);$employee=trim((string)($_POST['employee_number']??''));$department=trim((string)($_POST['department']??''));if(!$userId||$employee==='')throw new RuntimeException('Choose a user and enter an employee number.');$q=$pdo->prepare("SELECT COUNT(*) FROM users WHERE id=:id AND status='active'");$q->execute(['id'=>$userId]);if(!(int)$q->fetchColumn())throw new RuntimeException('Choose an active user.');$q=$pdo->prepare("INSERT INTO staff (user_id,employee_number,department,employment_status) VALUES (:user,:employee,:department,'active')");$q->execute(['user'=>$userId,'employee'=>$employee,'department'=>$department?:null]);$id=(int)$pdo->lastInsertId();(new AuditService())->record((int)$user['id'],'staff.create','staff',$id);$message='Staff profile created.';
  }elseif($action==='create_assignment'&&$canAssign){$staff=(int)($_POST['staff_id']??0);$year=(int)($_POST['academic_year_id']??0);$class=(int)($_POST['class_group_id']??0);$subject=(int)($_POST['subject_id']??0);$stream=(int)($_POST['stream_id']??0);if(!$staff||!$year||!$class||!$subject)throw new RuntimeException('Choose a staff member, year, class and subject.');$q=$pdo->prepare("SELECT COUNT(*) FROM staff s JOIN users u ON u.id=s.user_id JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id JOIN class_groups c ON c.id=:class WHERE s.id=:staff AND s.employment_status='active' AND u.status='active' AND c.academic_year_id=:year AND r.name IN ('class_teacher','subject_teacher','head_teacher','academic_admin')");$q->execute(['staff'=>$staff,'class'=>$class,'year'=>$year]);if(!(int)$q->fetchColumn())throw new RuntimeException('The staff member must have an active teaching or academic role, and the class must match the academic year.');if($stream){$q=$pdo->prepare('SELECT COUNT(*) FROM streams WHERE id=:stream AND class_group_id=:class');$q->execute(['stream'=>$stream,'class'=>$class]);if(!(int)$q->fetchColumn())throw new RuntimeException('The stream does not belong to the selected class.');}$q=$pdo->prepare('INSERT INTO teacher_assignments (staff_id,academic_year_id,class_group_id,stream_id,subject_id) VALUES (:staff,:year,:class,:stream,:subject)');$q->execute(['staff'=>$staff,'year'=>$year,'class'=>$class,'stream'=>$stream?:null,'subject'=>$subject]);$id=(int)$pdo->lastInsertId();(new AuditService())->record((int)$user['id'],'staff.assignment.create','teacher_assignments',$id,['staff_id'=>$staff,'class_group_id'=>$class,'subject_id'=>$subject]);$message='Teaching assignment created.';
  }else{http_response_code(403);throw new RuntimeException('You cannot perform that staff action.');}
 }catch(Throwable $exception){$error=$exception instanceof PDOException?'A duplicate staff profile or assignment already exists.':$exception->getMessage();}}
$unprofiled=$canStaff?$pdo->query("SELECT u.id,u.full_name,u.username,GROUP_CONCAT(r.label ORDER BY r.label SEPARATOR ', ') role_labels FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id LEFT JOIN staff s ON s.user_id=u.id WHERE u.status='active' AND s.id IS NULL GROUP BY u.id,u.full_name,u.username ORDER BY u.full_name")->fetchAll():[];$staff=$pdo->query("SELECT s.id,s.employee_number,s.department,s.employment_status,u.full_name,u.username,GROUP_CONCAT(DISTINCT r.label ORDER BY r.label SEPARATOR ', ') role_labels FROM staff s JOIN users u ON u.id=s.user_id LEFT JOIN user_roles ur ON ur.user_id=u.id LEFT JOIN roles r ON r.id=ur.role_id GROUP BY s.id,s.employee_number,s.department,s.employment_status,u.full_name,u.username ORDER BY u.full_name")->fetchAll();$years=$pdo->query("SELECT id,name FROM academic_years WHERE status IN ('active','planned') ORDER BY starts_on DESC")->fetchAll();$classes=$pdo->query('SELECT c.id,c.name,c.academic_year_id,y.name year_name FROM class_groups c JOIN academic_years y ON y.id=c.academic_year_id ORDER BY y.starts_on DESC,c.name')->fetchAll();$subjects=$pdo->query('SELECT id,code,name FROM subjects WHERE active=1 ORDER BY name')->fetchAll();$streams=$pdo->query('SELECT id,class_group_id,name FROM streams ORDER BY name')->fetchAll();$assignments=$pdo->query("SELECT ta.id,ta.ended_at,y.name year_name,c.name class_name,su.name subject_name,u.full_name teacher_name,st.employee_number FROM teacher_assignments ta JOIN staff st ON st.id=ta.staff_id JOIN users u ON u.id=st.user_id JOIN academic_years y ON y.id=ta.academic_year_id JOIN class_groups c ON c.id=ta.class_group_id JOIN subjects su ON su.id=ta.subject_id ORDER BY y.starts_on DESC,c.name,su.name")->fetchAll();$schoolName=(string)($pdo->query('SELECT name FROM school_profile ORDER BY id LIMIT 1')->fetchColumn()?:'School Management');$schoolRole=$role;$pageTitle='Staff & assignments';require dirname(__DIR__).'/includes/header.php';
?>
<div class="page-head"><div><h4>Staff & assignments</h4><p>Maintain staff profiles and map teachers to the classes and subjects they teach.</p></div></div><?php if($message!==''): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if($error!==''): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
<?php if($canStaff||$canAssign): ?><div class="row g-3 mb-3"><?php if($canStaff): ?><div class="col-xl-5"><div class="card h-100"><div class="card-header"><span class="card-title-sm"><i class="bi bi-person-badge me-1"></i>Register staff profile</span></div><div class="card-body"><p class="small text-muted">This links an existing active school login to its employment record. User accounts and passwords are managed separately.</p><form method="post" class="row g-2"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="create_staff"><div class="col-12"><label class="form-label">Existing user</label><select class="form-select" name="user_id" required><option value="">Choose account</option><?php foreach($unprofiled as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['full_name'].' · '.($u['username']??'').' · '.$u['role_labels']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Employee number</label><input class="form-control" name="employee_number" maxlength="40" required></div><div class="col-md-6"><label class="form-label">Department</label><input class="form-control" name="department" maxlength="100"></div><div class="col-12"><button class="btn btn-primary btn-sm"><i class="bi bi-person-plus me-1"></i>Save staff profile</button></div></form></div></div></div><?php endif; ?><?php if($canAssign): ?><div class="col-xl-7"><div class="card h-100"><div class="card-header"><span class="card-title-sm"><i class="bi bi-diagram-3 me-1"></i>Assign teaching responsibility</span></div><div class="card-body"><form method="post" class="row g-2"><?= SchoolAuth::csrfField() ?><input type="hidden" name="action" value="create_assignment"><div class="col-md-6"><label class="form-label">Staff member</label><select name="staff_id" class="form-select" required><option value="">Choose staff</option><?php foreach($staff as $member)if($member['employment_status']==='active'): ?><option value="<?= (int)$member['id'] ?>"><?= e($member['full_name'].' · '.$member['employee_number']) ?></option><?php endif; ?></select></div><div class="col-md-6"><label class="form-label">Academic year</label><select name="academic_year_id" class="form-select" required><option value="">Choose year</option><?php foreach($years as $year): ?><option value="<?= (int)$year['id'] ?>"><?= e($year['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Class</label><select name="class_group_id" class="form-select" required><option value="">Choose class</option><?php foreach($classes as $class): ?><option value="<?= (int)$class['id'] ?>"><?= e($class['year_name'].' · '.$class['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Subject</label><select name="subject_id" class="form-select" required><option value="">Choose subject</option><?php foreach($subjects as $subject): ?><option value="<?= (int)$subject['id'] ?>"><?= e($subject['name'].' ('.$subject['code'].')') ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Stream (optional)</label><select name="stream_id" class="form-select"><option value="0">Whole class</option><?php foreach($streams as $stream): ?><option value="<?= (int)$stream['id'] ?>"><?= e($stream['name']) ?></option><?php endforeach; ?></select></div><div class="col-12"><button class="btn btn-outline-primary btn-sm"><i class="bi bi-link-45deg me-1"></i>Create assignment</button></div></form></div></div></div><?php endif; ?></div><?php endif; ?>
<div class="card mb-3"><div class="card-header"><span class="card-title-sm"><i class="bi bi-people me-1"></i>Staff register</span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Employee</th><th>Staff number</th><th>Department</th><th>Roles</th><th>Status</th></tr></thead><tbody><?php foreach($staff as $member): ?><tr><td><?= e($member['full_name']) ?><div class="small text-muted"><?= e($member['username']??'') ?></div></td><td><?= e($member['employee_number']) ?></td><td><?= e($member['department']??'—') ?></td><td><?= e($member['role_labels']??'—') ?></td><td><?= e($member['employment_status']) ?></td></tr><?php endforeach; ?><?php if(!$staff): ?><tr><td colspan="5" class="text-center text-muted py-3">No staff profiles have been registered.</td></tr><?php endif; ?></tbody></table></div></div>
<div class="card"><div class="card-header"><span class="card-title-sm"><i class="bi bi-journal-bookmark me-1"></i>Teaching assignments</span></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Teacher</th><th>Year</th><th>Class</th><th>Subject</th><th>Status</th></tr></thead><tbody><?php foreach($assignments as $assignment): ?><tr><td><?= e($assignment['teacher_name']) ?><div class="small text-muted"><?= e($assignment['employee_number']) ?></div></td><td><?= e($assignment['year_name']) ?></td><td><?= e($assignment['class_name']) ?></td><td><?= e($assignment['subject_name']) ?></td><td><?= $assignment['ended_at']?'Ended':'Active' ?></td></tr><?php endforeach; ?><?php if(!$assignments): ?><tr><td colspan="5" class="text-center text-muted py-3">No teaching assignments are set up.</td></tr><?php endif; ?></tbody></table></div></div>
<?php require dirname(__DIR__).'/includes/footer.php'; ?>
